Catalog & Search.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Catalog & Search container

Container_Boundary("Catalog & Search", "Catalog & Search Container") {
    Component("Catalog & Search Controller", "Catalog & Search Controller", "Spring Boot", "Handles incoming REST/gRPC catalog and search requests and enforces JWT authentication.")
    Component("Search Service", "Search Service", "Spring Boot Service", "Executes full-text search, auto-suggestions, and faceted filtering operations.")
    Component("Product Repository", "Product Repository", "AWS SDK", "Retrieves canonical product details and pricing from data storage.")
}

Rel("Catalog & Search Controller", "Search Service", "Delegates search and catalog requests")
Rel("Search Service", "Product Repository", "Queries product metadata", "AWS SDK")

@enduml
